'use client';

import { useState } from 'react';

import {
  type AutoplayStep,
  useAutoplay,
} from '@/registry/ndeko/hooks/use-autoplay';
import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { HERO, ORDER } from './data';
import { GridLayer } from './grid-layer';

const SWAP_EVERY_MS = 1400;

export default function Heroes08() {
  const [step, setStep] = useState(0);

  function advance() {
    setStep((current) => (current + 1) % ORDER.length);
  }

  function startOver() {
    setStep(0);
  }

  const steps: AutoplayStep[] = ORDER.map(() => ({
    after: SWAP_EVERY_MS,
    run: advance,
  }));
  const { ref } = useAutoplay(steps, { loopAfter: 0, onReset: startOver });

  return (
    <section className='@container'>
      <div ref={ref} className='relative isolate min-h-[36rem] overflow-hidden'>
        <GridLayer step={step} />
        <div className='relative mx-auto flex max-w-3xl flex-col items-center px-4 py-24 @2xl:py-32'>
          <div className='bg-background flex flex-col items-center gap-6 rounded-2xl text-center shadow-[0_0_2.5rem_2rem_var(--background)]'>
            <p className='text-primary-ink text-sm font-medium'>
              {HERO.eyebrow}
            </p>
            <h1 className='text-4xl font-semibold text-balance @2xl:text-5xl'>
              {HERO.title}
            </h1>
            <p className='text-muted-foreground max-w-xl text-base text-pretty'>
              {HERO.description}
            </p>
            <div className='flex flex-wrap justify-center gap-2 pt-1'>
              <Button size='lg' nativeButton={false} render={<a href='#' />}>
                {HERO.primaryAction}
                <ArrowRightIcon />
              </Button>
              <Button
                size='lg'
                variant='outline'
                nativeButton={false}
                render={<a href='#' />}
              >
                {HERO.secondaryAction}
              </Button>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

import type { CSSProperties } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';

import { CELLS, COLUMNS, type GridCell, LIT_COUNT, ORDER } from './data';

const LINE = 'var(--border) var(--hairline), transparent var(--hairline)';

const GRID_STYLE: CSSProperties = {
  backgroundImage: `linear-gradient(to right, ${LINE}), linear-gradient(to bottom, ${LINE})`,
  backgroundSize: 'var(--cell) var(--cell)',
};

const BOARD_STYLE: CSSProperties = {
  width: `calc(var(--cell) * ${COLUMNS})`,
};

const LINES_FADE =
  '[mask-image:radial-gradient(ellipse_70%_80%_at_50%_45%,black_40%,transparent_100%)]';

type CellStyle = CSSProperties & {
  '--column': number;
  '--row': number;
};

function cellStyleOf(cell: GridCell) {
  const style: CellStyle = { '--column': cell.column, '--row': cell.row };
  return style;
}

function isLitAt(step: number, cellIndex: number) {
  const rank = ORDER.indexOf(cellIndex);
  const count = ORDER.length;
  const shifted = rank - step + count;
  const distance = shifted % count;
  return distance < LIT_COUNT;
}

function litOf(isLit: boolean) {
  if (isLit) {
    return '';
  }
  return undefined;
}

type GridLayerProps = {
  step: number;
};

export function GridLayer({ step }: GridLayerProps) {
  return (
    <div
      aria-hidden='true'
      className='pointer-events-none absolute inset-0 overflow-hidden [--cell:4.5rem]'
    >
      <div
        style={BOARD_STYLE}
        className='absolute inset-y-0 left-1/2 -translate-x-1/2'
      >
        <div
          style={GRID_STYLE}
          className={cn('absolute inset-0', LINES_FADE)}
        />
        {CELLS.map((cell, index) => {
          const isLit = isLitAt(step, index);
          return (
            <span
              key={cell.name}
              style={cellStyleOf(cell)}
              data-lit={litOf(isLit)}
              className='absolute top-[calc(var(--cell)*var(--row))] left-[calc(var(--cell)*var(--column))] flex size-(--cell) scale-90 items-center justify-center opacity-0 transition-[opacity,scale] duration-300 ease-(--ease-out-strong) data-lit:scale-100 data-lit:opacity-100 data-lit:duration-500 motion-reduce:transition-none'
            >
              <BrandTile brand={cell.brand} size='2xl' />
            </span>
          );
        })}
      </div>
    </div>
  );
}

import type { BrandSlug } from '@/registry/ndeko/lib/brand-logos';

export type GridCell = {
  name: string;
  brand: BrandSlug;
  column: number;
  row: number;
};

export const HERO = {
  eyebrow: 'Integrations',
  title: 'Bring every app your team uses into one workspace',
  description:
    'Connect calendars, trackers, files and payments once. Each app keeps its own rules, and a single feed shows what changed across all of them.',
  primaryAction: 'Connect your first app',
  secondaryAction: 'Browse the integrations',
};

export const COLUMNS = 21;

export const CELLS: GridCell[] = [
  { name: 'Google Calendar', brand: 'googlecalendar', column: 2, row: 1 },
  { name: 'Gmail', brand: 'gmail', column: 4, row: 2 },
  { name: 'Notion', brand: 'notion', column: 3, row: 4 },
  { name: 'Google Drive', brand: 'googledrive', column: 5, row: 5 },
  { name: 'Zoom', brand: 'zoom', column: 2, row: 6 },
  { name: 'GitHub', brand: 'github', column: 18, row: 1 },
  { name: 'Linear', brand: 'linear', column: 16, row: 2 },
  { name: 'Figma', brand: 'figma', column: 17, row: 4 },
  { name: 'Stripe', brand: 'stripe', column: 15, row: 5 },
  { name: 'Jira', brand: 'jira', column: 18, row: 6 },
  { name: 'Sentry', brand: 'sentry', column: 8, row: 0 },
  { name: 'HubSpot', brand: 'hubspot', column: 12, row: 0 },
  { name: 'Shopify', brand: 'shopify', column: 9, row: 7 },
  { name: 'Zapier', brand: 'zapier', column: 11, row: 7 },
];

/**
 * The order in which cells light up, as indexes of `CELLS`. Any five cells in a row of this list,
 * the end of the list joining its start, are at least two cells apart, so two neighbours never
 * show a tile together, not even while one fades out and the next fades in.
 */
export const ORDER = [0, 5, 10, 13, 3, 8, 11, 12, 2, 7, 1, 6, 4, 9];

export const LIT_COUNT = 4;
